// @angular/router, so the router half is yours. A FACTORY: inject()
// inside href/navigate would run outside an injection context.
provideSvLinkAdapter(() => {
  const router = inject(Router);
  const seg = (t: SvLinkTarget) => (typeof t === 'string' ? [t] : [...t]);
  return {
    kind: 'angular-router',
    href: (t) => router.serializeUrl(router.createUrlTree(seg(t))),
