})

persist(e: CartQuantityCommitEvent) {
  this.writing.set(true);
  // requestKey makes a retried request land once, not twice.
  this.api.setQty(this.lineId, e.quantity, e.requestKey).subscribe({
    next:  () => this.writing.set(false),
    error: (err) => {
