// searchRequest carries a token and an AbortSignal alongside the term.
protected async search({ term, signal }: CommandPaletteSearch): Promise<void> {
  this.searching.set(true);
  try {
    this.results.set(await this.api.search(term, signal));
    this.answeredTerm.set(term);        // ← what resultsFor reads
  } finally {
    this.searching.set(false);
  }
}

onReact(e: CommentReactEvent) {
  this.busy.update(ids => [...ids, e.commentId]);   // bind to [busyIds]
  this.api.react(e.commentId, e.emoji, e.reacted, e.requestKey).subscribe({
    // Write what the event says, not a toggle of what is in the array — the
    // same answer arriving twice must not invert it back.
    next:  () => { this.comments.update(l => write(l, e)); this.settle(e); },
    error: (err) => { e.rollback(); this.failure.set(err); this.settle(e); },
  });
}

remove(id: string) {
  this.comments.update(list => list.map(c =>
    c.id === id && c.replies?.length
      ? { ...c, deleted: true, content: '', authorName: '', reactions: [] }
      : c,
  ).filter(c => c.id !== id || !!c.deleted));
}

onReply(e: { parentId: string; text: string }) {
  this.busy.update(ids => [...ids, e.parentId]);
  this.api.post(e).subscribe({
    next:  (thread) => { this.comments.set(thread); this.settle(e.parentId); },
    error: (err) => {
      this.failures.update(m => ({ ...m, [e.parentId]: err }));   // [commentErrors]
      this.settle(e.parentId);
    },
  });
}

