// There is no rollback() here, unlike every other write in the kit: this
// component renders ONE file, and the list it sits in belongs to you, so it has
// nothing to put itself back into. What it offers instead is the step before —
// an inline confirmation, on by default.
onRemove(event: FileRemoveEvent): void {
  this.deleteError.set(null);
  this.deleting.update(s => new Set(s).add(event.fileName));

  // requestKey makes the delete idempotent: a retried request cannot delete
  // whatever has since taken the same name.
  this.api.deleteFile(event.fileName, event.requestKey).subscribe({
    next: () => this.files.update(list => list.filter(f => f.name !== event.fileName)),
    error: () => this.deleteError.set('The file could not be deleted.'),
    complete: () => this.deleting.update(s => { const n = new Set(s); n.delete(event.fileName); return n; }),
  });
}

