import { svChunkedUploader } from '@styloviz-pro/file-upload';

upload = svChunkedUploader({
  // How many bytes the server already has. Optional; a failure here just means
  // starting from the beginning rather than failing the upload.
  probe: ({ key, signal }) =>
    fetch(`/api/uploads/${key}`, { signal })
      .then(r => (r.ok ? r.json().then(j => j.bytes) : 0)),

  sendChunk: ({ key, blob, chunk, signal }) =>
    fetch(`/api/uploads/${key}`, {
      method: 'PATCH',
      headers: { 'Upload-Offset': String(chunk.start) },
      body: blob,
      signal,
    }).then(r => {
      // Attach the status so the retry policy can read it: a 503 is retried,
      // a 413 is not — retrying a body that is over the limit uploads it in
      // full, five times, to fail identically every time.
      if (!r.ok) throw Object.assign(new Error(r.statusText), { status: r.status });
    }),

  complete: ({ key, signal }) =>
    fetch(`/api/uploads/${key}/complete`, { method: 'POST', signal }).then(r => r.json()),
});

