import { svChunkedUploader, svLocalResumeStore, svCanResume } from '@styloviz-pro/file-upload';

const store = svLocalResumeStore({ scope: currentUser.id });
store.prune(24 * 60 * 60 * 1000);

uploader = svChunkedUploader({
  probe: async ({ file, key, signal }) => {
    const saved = store.get(key);
    if (svCanResume(saved, file)) {
      const res = await fetch(saved!.uploadUrl, { method: 'HEAD', signal });
      if (res.ok) return Number(res.headers.get('Upload-Offset') ?? 0);
    }
    const created = await fetch('/api/uploads', { method: 'POST', signal });
    store.set({ key, uploadUrl: created.headers.get('Location')!, size: file.size,
                lastModified: file.lastModified, createdAt: Date.now() });
    return 0;
  },
  sendChunk: ({ key, blob, chunk, signal }) =>
    fetch(store.get(key)!.uploadUrl, { method: 'PATCH', body: blob, signal,
      headers: { 'Upload-Offset': String(chunk.start) } }).then((r) => {
      if (!r.ok) throw Object.assign(new Error(r.statusText), { status: r.status });
    }),
  complete: async ({ key }) => { store.remove(key); },
});

