// The panel takes [notifications] as an input, so merging is yours.
// svMergeRecords answers the four questions a live list asks -
// identity, version, deduplication and order - and reports what it
// did, so a stream that keeps redelivering stale revisions is visible
// rather than silent.
import { svMergeRecords } from '@styloviz/core';

socket.on('notification', (incoming) => {
  const merge = svMergeRecords(this.items(), [incoming]);
  this.items.set(merge.items);

  // A lower version than the copy held: refused, and worth knowing.
  if (merge.rejected.length) console.warn('stale', merge.rejected);

  // Rows dropped because they share a dedupeKey. The headline is yours
  // to write - "and 2 more comments" - which is why no count is
  // written onto the survivor.
  if (merge.collapsed.length) this.noteCollapsed(merge.collapsed);
});

