import {
  svQueryToPredicate, type SvQueryPredicate, type SvQueryOperator,
} from '@styloviz-pro/query-builder';

// This component escapes NOTHING and emits no query language. Translation is
// your side of the boundary, and it is where a value the user typed becomes
// code. svQueryToPredicate() hands the query over already split into the parts
// you must treat differently — your field ids, a closed operator set, and the
// user's raw params.
const OPERATORS: Partial<Record<SvQueryOperator, string>> = { eq: '= ?', gt: '> ?', contains: 'LIKE ?' };
const COLUMNS: Record<string, string> = { country: 'c.country_code', age: 'c.age' }; // your allow-list

function toSql(node: SvQueryPredicate): { sql: string; params: unknown[] } {
  if (node.kind === 'group') {
    const parts = node.children.map(toSql);
    const join = node.combinator === 'and' ? ' AND ' : ' OR ';
    return { sql: `(${parts.map(p => p.sql).join(join)})`, params: parts.flatMap(p => p.params) };
  }
  // A date term arrives with its instant range already resolved, in the zone you
  // passed. Compare against that, not the raw day in params — a timestamp column
  // otherwise disagrees with the user's calendar by up to a day.
  if (node.dateWindow) {
    const { fromInclusive, toExclusive } = node.dateWindow;
    const bounds = [
      fromInclusive && { sql: `${COLUMNS[node.field]} >= ?`, param: fromInclusive },
      toExclusive && { sql: `${COLUMNS[node.field]} < ?`, param: toExclusive },
    ].filter(Boolean) as { sql: string; param: string }[];
    return { sql: `(${bounds.map(b => b.sql).join(' AND ')})`, params: bounds.map(b => b.param) };
  }

  const column = COLUMNS[node.field];        // never the raw field id
  const fragment = OPERATORS[node.operator]; // never the raw operator
  if (!column || !fragment) throw new Error(`unsupported: ${node.field} ${node.operator}`);
  return { sql: `${column} ${fragment}`, params: [...node.params] }; // params stay BOUND
}

