// An Undo instead of a confirm prompt. `action` takes a label and a
// callback; pressing it runs the callback and dismisses the toast.
const id = this.toast.info('Invoice INV-2041 archived', {
  duration: 8000,
  action: { label: 'Undo', callback: () => this.restore('INV-2041') },
});

// The returned id dismisses it early — e.g. if the user undid it elsewhere.
this.toast.dismiss(id);

// A spinner and "Saving…" while the work runs — it cannot time out or be
// closed until the work settles — then the SAME toast becomes the outcome,
// announced again. It returns the work's own promise.
await this.toast.promise(this.api.save(rows), {
  loading: 'Saving…',
  success: (saved) => `Saved ${saved.length} rows`,
  error: (e) => `Could not save: ${describe(e)}`,
});

// Deduplication is on by default. Eleven identical failures are one
// toast with a x11 badge and a countdown that restarts from the last
// one - not eleven toasts that evict every other message in a stack
// bounded at five.
for (const attempt of attempts) {
  try { await attempt(); }
  catch { this.toast.error('Sync failed'); }
}

// An explicit key deduplicates on the SUBJECT rather than the wording,
// so these two replace each other instead of stacking.
this.toast.info('Saving...', { dedupeKey: 'record-7', duration: 0 });
await this.save();
this.toast.success('Saved', { dedupeKey: 'record-7' });

// And opt a single call out when two identical sentences are genuinely
// two events the user must see separately.
this.toast.info('Row added', { dedupeKey: null });

// The default is scope: 'global', and it is the right default: the
// commonest toast in any app is raised BY the action that navigates,
// and it has to survive that navigation to be read at all.
await this.save();
this.toast.success('Invoice saved');       // survives
this.router.navigate(['/invoices']);

// A message about the view the user is looking at is stale the moment
// they leave it. Say so, and provideSvOverlayRouteClose() drops it on
// the next navigation.
this.toast.warning('3 filters could not be applied to this view', {
  scope: 'route',
});

// pending: spinner + aria-busy + inert click (still focusable)
// shortcut: aria-keyshortcuts + sv-kbd chips in the tooltip and menu row
