onTransfer(event: TransferChangeEvent): void {
  this.saving.set(true);
  // `moved` is just the items that changed hands — no diffing the two panes.
  this.api.grant({
    keys: event.moved.map(i => i.key),
    direction: event.direction,
    requestKey: event.requestKey,   // ignore a key already applied
  }).subscribe({
    next: () => {
      // Only on success: a rejected move is rolled back inside the component.
      this.available.set([...event.source]);
      this.selected.set([...event.target]);
      this.saving.set(false);
    },
    error: () => {
      event.rollback();             // panes AND ticks go back
      this.moveError.set('Could not save that move.');
      this.saving.set(false);
    },
  });
}

