// Ids must be unique and STABLE — the id is what a saved layout stores, so one
// derived from an array index rearranges the dashboard whenever the array does.

// The grid rearranges before the server has heard about it, so it hands back
// the only copy of the previous layout. Bind [savingLayout] so a second change
// cannot start on top of the first, and rollback() stays unambiguous.
saveLayout(event: WidgetGridLayout): void {
  this.error.set(null);
  this.saving.set(true);

  this.api
    .saveLayout({ order: event.order, hidden: event.hidden, requestKey: event.requestKey })
    .subscribe({
      next:  () => this.saving.set(false),
      error: () => {
        // Restores order AND hidden set, and unwrites the persistKey copy, so a
        // reload does not bring the failed layout back.
        event.rollback();
        this.error.set('Could not save your layout.');
        this.saving.set(false);
      },
    });
}

async onSwitch({ to }: WorkspaceSwitchRequest) {
