import { menuIcon } from '@styloviz/icons/glyph/menu';

/** One link in the bar. */
export interface NavbarLink {
  readonly label: string;
  readonly href: string;
}

let nextId = 0;

/**
 * Marketing navigation bar — wordmark, primary links, "Sign in" and "Start
 * free". Below `md` the links fold into a disclosure panel behind a menu
 * button; Escape closes it and puts focus back on the button.
 */
@Component({
  selector: 'app-navbar-simple',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [SvButtonComponent, SvIconComponent],
  // Escape anywhere closes an open menu (and does nothing when it is shut).
  host: { '(document:keydown.escape)': 'close(true)' },
  template: `
    <header class="border-b border-gray-200 bg-white dark:border-white/10 dark:bg-gray-950">
      <div class="mx-auto flex h-16 w-full max-w-6xl items-center gap-6 px-5 sm:px-8">
