          <span class="flex h-7 w-7 items-center justify-center rounded-lg bg-gradient-to-br from-primary-700 to-accent-700 text-sm font-bold text-white" aria-hidden="true">L</span>
          <span>Ledger<span class="text-primary-700 dark:text-primary-300">line</span></span>
        </a>

        <nav class="hidden flex-1 items-center gap-1 md:flex" aria-label="Main">
          @for (link of links(); track link.href) {
            <a [href]="link.href" class="rounded-lg px-3 py-2 text-sm font-medium text-gray-600 transition-colors hover:bg-gray-100 hover:text-gray-900 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary-500 dark:text-gray-300 dark:hover:bg-white/5 dark:hover:text-white">
              {{ link.label }}
