          }
        </nav>

        <div class="ms-auto flex items-center gap-2">
          <sv-button class="hidden sm:block" btnStyle="ghost" variant="neutral" size="sm" label="Sign in" [href]="signInHref()" />
          <sv-button size="sm" label="Start free" [href]="startHref()" />
          <button
            #menuButton
