export class HeroCenteredSignupComponent {
  protected readonly icons = registerSvIcons([checkIcon, checkCircleIcon]);

  /** The address, once it validates. */
  readonly signUp = output<string>();

  protected readonly inputId = `hero-signup-email-${nextId++}`;
  protected readonly assurances = ['14-day trial', 'No card required', 'Cancel any time'] as const;
  protected readonly email = signal('');
  protected readonly done = signal(false);
  private readonly attempted = signal(false);

  protected readonly emailError = computed(() => {
    if (!this.attempted()) return '';
    const value = this.email().trim();
    if (!value) return 'Enter your work email to get started.';
    return EMAIL.test(value) ? '' : 'That does not look like an email address.';
  });

  protected submit(): void {
    this.attempted.set(true);
    if (this.emailError()) return;
    this.signUp.emit(this.email().trim());
    this.done.set(true);
  }
}

