    { label: 'Connect Stripe', href: '/docs/sources/stripe' },
    { label: 'MRR definitions', href: '/docs/metrics/mrr' },
    { label: 'REST API', href: '/docs/api' },
  ]);
  /** The trimmed query, when it is not empty. */
  readonly searchSubmit = output<string>();

  protected readonly uid = `hero-docs-search-${nextId++}`;
  protected readonly query = signal('');
  protected readonly safeLinks = computed(() => this.popularLinks().filter((l) => l.label.trim() && SAFE_HREF.test(l.href)));

