import { ChangeDetectionStrategy, Component, computed, input } from '@angular/core';
import { SvIconComponent, registerSvIcons } from '@styloviz/icons';
import { trendingDownIcon } from '@styloviz/icons/glyph/trending-down';
import { trendingUpIcon } from '@styloviz/icons/glyph/trending-up';

let nextId = 0;

export interface TrendStat {
  readonly label: string;
  readonly value: string;
  /** Percentage change on the comparison period; negative is down. */
  readonly change: number;
  /** False for metrics where down is good, such as churn. Defaults to true. */
  readonly higherIsBetter?: boolean;
}

/**
 * Four KPI cards, each with a value, a label and a trend chip. The chip is
 * green when the move is good and red when it is bad — so falling churn reads
 * as good news — and carries screen-reader text such as "up 12% on last month".
 */
@Component({
  selector: 'app-stats-cards-trend',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [SvIconComponent],
  template: `
    <section class="mx-auto w-full max-w-6xl px-5 py-12 sm:px-8 sm:py-16" [attr.aria-labelledby]="uid + '-title'">
      <h2 [id]="uid + '-title'" class="text-lg font-semibold tracking-tight text-gray-900 dark:text-white">{{ heading() }}</h2>
      <dl class="mt-6 grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4">
        @for (stat of view(); track stat.label) {
          <div class="flex flex-col rounded-2xl bg-white p-5 shadow-sm ring-1 ring-gray-200 dark:bg-gray-900 dark:shadow-none dark:ring-white/10">
            <dt class="text-sm font-medium text-gray-600 dark:text-gray-400">{{ stat.label }}</dt>
            <dd class="mt-2 flex flex-wrap items-baseline justify-between gap-2">
              <span class="text-3xl font-semibold tracking-tight text-gray-900 tabular-nums dark:text-white">{{ stat.value }}</span>
              <span class="inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-xs font-semibold tabular-nums" [class]="stat.tone">
                <sv-icon [name]="stat.icon" cssClass="h-3.5 w-3.5" />
                <span aria-hidden="true">{{ stat.shown }}</span>
                <span class="sr-only">{{ stat.spoken }}</span>
              </span>
            </dd>
          </div>
        }
      </dl>
    </section>
  `,
})
export class StatsCardsTrendComponent {
  protected readonly icons = registerSvIcons([trendingUpIcon, trendingDownIcon]);

  /** The heading above the cards. */
  readonly heading = input('October at a glance');
  /** What the change is measured against, used in the screen-reader text. */
  readonly period = input('last month');
  /** The cards; a non-finite `change` is shown as 0%. */
  readonly stats = input<readonly TrendStat[]>([
    { label: 'Monthly recurring revenue', value: '$482,190', change: 12 },
    { label: 'Net revenue retention', value: '114%', change: 2.1 },
    { label: 'New trials', value: '1,284', change: -6.4 },
    { label: 'Logo churn', value: '1.9%', change: -0.8, higherIsBetter: false },
  ]);

  protected readonly uid = `stats-cards-trend-${nextId++}`;
  protected readonly view = computed(() =>
    this.stats().map((stat) => {
      const change = Number.isFinite(stat.change) ? stat.change : 0;
      const up = change >= 0;
      const good = up === (stat.higherIsBetter ?? true);
      const amount = `${Math.abs(change).toLocaleString('en-US', { maximumFractionDigits: 1 })}%`;
      return {
        label: stat.label,
        value: stat.value,
        icon: up ? 'trending-up' : 'trending-down',
        shown: `${up ? '+' : '−'}${amount}`,
        spoken: `${up ? 'up' : 'down'} ${amount} on ${this.period()}`,
        tone: good
          ? 'bg-accent-50 text-accent-700 dark:bg-accent-500/15 dark:text-accent-300'
          : 'bg-danger-50 text-danger-700 dark:bg-danger-500/15 dark:text-danger-300',
      };
    }),
  );
