/** What the form emits once every field validates. */
export interface ContactMessage {
  readonly name: string;
  readonly email: string;
  readonly message: string;
}

const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
let nextId = 0;

/**
 * Contact section — how to reach the team on the left, a validated
 * name / email / message form on the right that swaps to a thank-you state.
 * Bind `(send)` to your inbox or helpdesk.
 */
@Component({
  selector: 'app-contact-split',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [SvButtonComponent, SvIconComponent, SvInputFieldComponent],
  template: `
    <section class="px-5 py-16 sm:px-8 sm:py-20" [attr.aria-labelledby]="uid + '-title'">
      <div class="mx-auto grid w-full max-w-6xl gap-12 lg:grid-cols-[minmax(0,2fr)_minmax(0,3fr)]">
        <div>
          <p class="text-xs font-semibold uppercase tracking-wider text-primary-700 dark:text-primary-300">Contact</p>
          <h2 [id]="uid + '-title'" class="mt-2 text-2xl font-semibold tracking-tight text-gray-900 sm:text-3xl dark:text-white">Talk to a human about your revenue data</h2>
          <p class="mt-3 text-base leading-relaxed text-gray-600 dark:text-gray-300">Questions about pricing, a migration or a number that looks off — we read every message.</p>
          <dl class="mt-8 space-y-5">
            @for (d of details; track d.term) {
              <div class="flex gap-4">
                <dt class="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-primary-50 text-primary-700 dark:bg-primary-500/10 dark:text-primary-300">
                  <sv-icon [name]="d.icon" cssClass="h-5 w-5" /><span class="sr-only">{{ d.term }}</span>
                </dt>
                <dd class="text-sm leading-6 text-gray-600 dark:text-gray-300">
                  <span class="block font-medium text-gray-900 dark:text-white">{{ d.value }}</span>{{ d.note }}
                </dd>
              </div>
            }
          </dl>
        </div>

        <div class="rounded-2xl border border-gray-200 bg-white p-6 shadow-sm sm:p-8 dark:border-white/10 dark:bg-gray-900">
          @if (sent()) {
            <div class="flex flex-col items-center py-10 text-center" role="status">
              <span class="flex h-12 w-12 items-center justify-center rounded-full bg-accent-100 text-accent-700 dark:bg-accent-500/20 dark:text-accent-300">
                <sv-icon name="check-circle" cssClass="h-6 w-6" />
              </span>
              <p class="mt-4 text-base font-semibold text-gray-900 dark:text-white">Thanks, {{ name().trim() }} — message received</p>
              <p class="mt-1 max-w-sm text-sm text-gray-600 dark:text-gray-300">We reply to {{ email().trim() }} within one business day.</p>
            </div>
          } @else {
            <form class="grid gap-5 sm:grid-cols-2" novalidate (submit)="$event.preventDefault(); submit()">
              <sv-input-field [inputId]="uid + '-name'" label="Name" autocomplete="name" [required]="true" [(value)]="name" [errorMessage]="nameError()" />
              <sv-input-field [inputId]="uid + '-email'" label="Work email" type="email" autocomplete="email" [required]="true" [(value)]="email" [errorMessage]="emailError()" />
              <sv-input-field class="sm:col-span-2" [inputId]="uid + '-message'" label="Message" [multiline]="true" [maxLength]="1000" placeholder="What can we help with?" [required]="true" [(value)]="message" [errorMessage]="messageError()" />
              <div class="sm:col-span-2">
                <sv-button type="submit" size="lg" label="Send message" trailingIcon="send" />
              </div>
            </form>
          }
        </div>
      </div>
    </section>
  `,
})
export class ContactSplitComponent {
  protected readonly icons = registerSvIcons([checkCircleIcon, clockIcon, mailIcon, mapPinIcon, phoneIcon, sendIcon]);

  /** A valid name, email and message. */
  readonly send = output<ContactMessage>();

  protected readonly uid = `contact-split-${nextId++}`;
  protected readonly details = [
    { term: 'Email', icon: 'mail', value: 'hello@ledgerline.example', note: 'Sales, support and billing.' },
    { term: 'Phone', icon: 'phone', value: '+44 20 7946 0321', note: 'Mon–Fri, 9:00–17:30 GMT.' },
    { term: 'Office', icon: 'map-pin', value: '14 Clerkenwell Green, London', note: 'EC1R 0DP, United Kingdom.' },
    { term: 'Response time', icon: 'clock', value: 'Under one business day', note: 'Usually a lot faster.' },
  ] as const;
  protected readonly name = signal('');
  protected readonly email = signal('');
  protected readonly message = signal('');
  protected readonly sent = signal(false);
  private readonly attempted = signal(false);

  protected readonly nameError = computed(() => (this.attempted() && !this.name().trim() ? 'Enter your name.' : ''));
  protected readonly emailError = computed(() => {
    if (!this.attempted()) return '';
    const value = this.email().trim();
    if (!value) return 'Enter your email.';
    return EMAIL.test(value) ? '' : 'That does not look like an email address.';
  });
  protected readonly messageError = computed(() => {
    if (!this.attempted()) return '';
    const length = this.message().trim().length;
    return length < 10 ? 'Tell us a little more — at least 10 characters.' : length > 1000 ? 'Keep it under 1,000 characters.' : '';
  });

  protected submit(): void {
    this.attempted.set(true);
    if (this.nameError() || this.emailError() || this.messageError()) return;
    this.send.emit({ name: this.name().trim(), email: this.email().trim(), message: this.message().trim() });
    this.sent.set(true);
  }
}

