let nextId = 0;

/**
 * Seasonal promo banner — headline, offer, a discount-code chip with a copy
 * button and an "ends in" line. Copying uses the Clipboard API and says
 * "Copied" (or what to do instead) in a live status message.
 */
@Component({
  selector: 'app-promo-banner',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [SvButtonComponent, SvIconComponent],
  template: `
