        <span class="absolute -end-24 -top-24 -z-10 h-72 w-72 rounded-full bg-accent-400/20" aria-hidden="true"></span>
        <span class="absolute -bottom-32 start-1/3 -z-10 h-72 w-72 rounded-full bg-white/5" aria-hidden="true"></span>

        <div class="grid items-center gap-8 lg:grid-cols-[minmax(0,1fr)_auto]">
          <div>
            <p class="text-xs font-semibold uppercase tracking-[0.16em] text-primary-100">{{ eyebrow() }}</p>
            <h2 [id]="uid + '-title'" class="mt-2 text-balance text-3xl font-bold tracking-tight sm:text-4xl">{{ headline() }}</h2>
            <p class="mt-3 max-w-xl text-base leading-relaxed text-primary-50">{{ offer() }}</p>
            <p class="mt-4 inline-flex items-center gap-1.5 text-sm font-medium text-primary-100">
              <sv-icon name="clock" cssClass="h-4 w-4" /> {{ endsIn() }}
            </p>
          </div>

          <div class="flex flex-col gap-3 sm:flex-row sm:items-center lg:flex-col lg:items-stretch">
            <div class="flex items-center gap-2 rounded-2xl bg-white/10 p-2 ring-1 ring-white/20">
              <span class="px-3 font-mono text-lg font-bold tracking-[0.2em]">{{ code() }}</span>
              <button
                type="button"
                class="ms-auto inline-flex min-h-10 items-center gap-1.5 rounded-xl bg-white px-3.5 text-sm font-semibold text-primary-800 transition-colors hover:bg-primary-50 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white focus-visible:ring-offset-2 focus-visible:ring-offset-primary-800"
                [attr.aria-label]="'Copy code ' + code()"
                (click)="copy()">
                <sv-icon [name]="copied() ? 'check' : 'copy'" cssClass="h-4 w-4" />
                {{ copied() ? 'Copied' : 'Copy' }}
              </button>
            </div>
            <sv-button size="lg" variant="neutral" btnStyle="soft" label="Shop the sale" trailingIcon="arrow-right" [href]="href()" />
            <p class="min-h-5 text-sm text-primary-50" role="status">{{ statusText() }}</p>
          </div>
        </div>
      </div>
    </section>
  `,
})
export class PromoBannerComponent {
  protected readonly icons = registerSvIcons([arrowRightIcon, checkIcon, clockIcon, copyIcon]);
  private readonly destroyRef = inject(DestroyRef);

  /** The small line above the headline. */
  readonly eyebrow = input('Autumn sale');
  /** The headline. */
  readonly headline = input('25% off everything for the outdoors');
  /** The offer in a sentence. */
  readonly offer = input('Packs, layers and camp kitchen — stack it with free shipping on orders over $75.');
  /** The discount code shown in the chip. */
  readonly code = input('AUTUMN25');
  /** The deadline, as it should read. */
  readonly endsIn = input('Ends Sunday, November 2 at midnight');
  /** Where "Shop the sale" goes. */
  readonly href = input('/c/sale');

  /** The code was copied to the clipboard. */
  readonly codeCopied = output<string>();

  protected readonly uid = `promo-banner-${nextId++}`;
  protected readonly copied = signal(false);
  protected readonly statusText = signal('');
  private timer: ReturnType<typeof setTimeout> | undefined;

  constructor() {
    this.destroyRef.onDestroy(() => clearTimeout(this.timer));
  }

  protected async copy(): Promise<void> {
    const code = this.code();
    try {
      if (typeof navigator === 'undefined' || !navigator.clipboard) throw new Error('Clipboard unavailable');
      await navigator.clipboard.writeText(code);
      this.copied.set(true);
      this.statusText.set(`Copied ${code} to the clipboard.`);
      this.codeCopied.emit(code);
    } catch {
      this.copied.set(false);
      this.statusText.set(`Could not copy — enter ${code} at checkout.`);
    }
    clearTimeout(this.timer);
    this.timer = setTimeout(() => {
      this.copied.set(false);
      this.statusText.set('');
    }, 2500);
  }
}

