export class AuthSignInCardComponent {
  protected readonly icons = registerSvIcons([githubIcon, googleIcon, lockIcon, mailIcon]);

  /** True while your sign-in request runs. */
  readonly pending = input(false);
  /** The server's reason the last attempt failed; empty hides the banner. */
  readonly error = input('');
  /** Where "Create an account" goes. */
  readonly registerHref = input('/register');
  /** Where "Forgot password?" goes. */
  readonly forgotHref = input('/forgot-password');

  /** A valid email and a non-empty password. */
  readonly signIn = output<SignInRequest>();
  /** The id of the identity provider clicked. */
  readonly provider = output<'google' | 'github'>();

  protected readonly uid = `sign-in-${nextId++}`;
  protected readonly providers = [
    { id: 'google', label: 'Continue with Google', icon: 'google' },
    { id: 'github', label: 'Continue with GitHub', icon: 'github' },
  ] as const;
  protected readonly email = signal('');
  protected readonly password = signal('');
  protected readonly remember = signal(true);
  private readonly attempted = signal(false);

  protected readonly emailError = computed(() => {
    if (!this.attempted()) return '';
    const value = this.email().trim();
    if (!value) return 'Enter your email.';
    return EMAIL.test(value) ? '' : 'That does not look like an email address.';
  });
  protected readonly passwordError = computed(() => (this.attempted() && !this.password() ? 'Enter your password.' : ''));

  protected submit(): void {
    this.attempted.set(true);
    if (this.pending() || this.emailError() || this.passwordError()) return;
    this.signIn.emit({ email: this.email().trim(), password: this.password(), remember: this.remember() });
  }
}

import { ChangeDetectionStrategy, Component, computed, input, output, signal } from '@angular/core';
import { SvAlertBannerComponent } from '@styloviz/alert-banner';
import { SvButtonComponent } from '@styloviz/button';
import { SvCheckboxComponent } from '@styloviz/forms';
import { registerSvIcons } from '@styloviz/icons';
import { lockIcon } from '@styloviz/icons/glyph/lock';
import { mailIcon } from '@styloviz/icons/glyph/mail';
import { userIcon } from '@styloviz/icons/glyph/user';
import { SvInputFieldComponent } from '@styloviz/input-field';

/** What the card emits on a valid submit. */
export interface SignUpRequest {
  readonly name: string;
  readonly email: string;
  readonly password: string;
}

const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const LEVELS = ['Too short', 'Weak', 'Fair', 'Good', 'Strong'] as const;
const BAR_ON = ['bg-danger-600', 'bg-danger-600', 'bg-warning-500', 'bg-primary-600', 'bg-accent-600'] as const;
let nextId = 0;

/**
 * Sign-up card — name, work email and a password with a live strength meter,
 * plus a required terms checkbox.
 *
