 * `[pending]` while the request runs and `[error]` when it fails.
 */
@Component({
  selector: 'app-auth-sign-up-card',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [SvAlertBannerComponent, SvButtonComponent, SvCheckboxComponent, SvInputFieldComponent],
  template: `
    <section class="bg-gray-50 px-4 py-12 sm:px-6 sm:py-16 dark:bg-gray-950">
      <div class="mx-auto w-full max-w-md rounded-2xl border border-gray-200 bg-white p-6 shadow-sm sm:p-8 dark:border-white/10 dark:bg-gray-900">
        <h2 class="text-2xl font-semibold tracking-tight text-gray-900 dark:text-white">Create your account</h2>
        <p class="mt-1.5 text-sm text-gray-600 dark:text-gray-400">
          Already have one?
          <a [href]="signInHref()" class="font-medium text-primary-700 hover:underline dark:text-primary-300">Sign in</a>
        </p>

        @if (error()) {
          <sv-alert-banner class="mt-5 block" variant="danger" alertStyle="soft" size="sm" [dismissible]="false" [message]="error()" />
        }

        <form class="mt-6 flex flex-col gap-4" novalidate (submit)="$event.preventDefault(); submit()">
          <sv-input-field [inputId]="uid + '-name'" label="Full name" placeholder="Maya Okafor" leadingIcon="user" autocomplete="name"
                          [required]="true" [(value)]="name" [errorMessage]="nameError()" />
          <sv-input-field [inputId]="uid + '-email'" label="Work email" type="email" placeholder="maya@northwind.io" leadingIcon="mail"
                          autocomplete="email" [required]="true" [(value)]="email" [errorMessage]="emailError()" />
          <div>
            <sv-input-field [inputId]="uid + '-password'" label="Password" type="password" placeholder="At least 8 characters"
                            leadingIcon="lock" autocomplete="new-password" [required]="true" [(value)]="password"
                            hint="Use 12+ characters with upper and lower case, a number and a symbol." [errorMessage]="passwordError()" />
            <div class="mt-2 flex items-center gap-3">
              <div class="grid flex-1 grid-cols-4 gap-1.5" aria-hidden="true">
                @for (bar of bars(); track $index) {
                  <span class="h-1.5 rounded-full" [class]="bar"></span>
                }
              </div>
              <span class="w-16 text-end text-xs font-medium text-gray-600 dark:text-gray-400" aria-hidden="true">{{ level() }}</span>
            </div>
            <p class="sr-only" aria-live="polite">Password strength: {{ level() }}</p>
          </div>
          <sv-checkbox size="sm" [inputId]="uid + '-terms'" [required]="true" [(checked)]="terms" [errorMessage]="termsError()"
                       label="I agree to the Terms of Service and Privacy Policy" />
          <p class="-mt-2 ps-7 text-xs text-gray-600 dark:text-gray-400">
            Read the <a [href]="termsHref()" class="font-medium text-primary-700 hover:underline dark:text-primary-300">Terms</a>
            and <a [href]="privacyHref()" class="font-medium text-primary-700 hover:underline dark:text-primary-300">Privacy Policy</a>.
          </p>
          <sv-button type="submit" size="lg" [block]="true" label="Create account" loadingLabel="Creating account" [loading]="pending()" />
        </form>
      </div>
    </section>
  `,
