export class AuthSignUpCardComponent {
  protected readonly icons = registerSvIcons([lockIcon, mailIcon, userIcon]);

  /** True while your sign-up request runs. */
  readonly pending = input(false);
  /** The server's reason the last attempt failed; empty hides the banner. */
  readonly error = input('');
  /** Where "Sign in" goes. */
  readonly signInHref = input('/login');
  /** Where the Terms of Service link goes. */
  readonly termsHref = input('/terms');
  /** Where the Privacy Policy link goes. */
  readonly privacyHref = input('/privacy');

  /** A named, valid email, an 8+ character password and accepted terms. */
  readonly signUp = output<SignUpRequest>();

  protected readonly uid = `sign-up-${nextId++}`;
  protected readonly name = signal('');
  protected readonly email = signal('');
  protected readonly password = signal('');
  protected readonly terms = signal(false);
  private readonly attempted = signal(false);

  /** 0–4: length earns two points, character variety the other two. */
  private readonly score = computed(() => {
    const value = this.password();
    if (value.length < 8) return 0;
    const classes = [/[a-z]/, /[A-Z]/, /\d/, /[^A-Za-z0-9]/].filter((re) => re.test(value)).length;
    return Math.min(4, 1 + (value.length >= 12 ? 1 : 0) + (classes >= 3 ? 1 : 0) + (classes === 4 ? 1 : 0));
  });
  protected readonly level = computed(() => (this.password() ? LEVELS[this.score()] : 'Not set'));
  protected readonly bars = computed(() => {
    const score = this.score();
    return [1, 2, 3, 4].map((i) => (i <= score ? BAR_ON[score] : 'bg-gray-200 dark:bg-white/10'));
  });

  protected readonly nameError = computed(() => (this.attempted() && !this.name().trim() ? 'Enter your name.' : ''));
  protected readonly emailError = computed(() => {
    if (!this.attempted()) return '';
    const value = this.email().trim();
    if (!value) return 'Enter your work email.';
    return EMAIL.test(value) ? '' : 'That does not look like an email address.';
