import { ChangeDetectionStrategy, Component, DestroyRef, computed, inject, input, output, signal } from '@angular/core';
import { SvAlertBannerComponent } from '@styloviz/alert-banner';
import { SvButtonComponent } from '@styloviz/button';
import { SvIconComponent, registerSvIcons } from '@styloviz/icons';
import { arrowLeftIcon } from '@styloviz/icons/glyph/arrow-left';
import { mailIcon } from '@styloviz/icons/glyph/mail';
import { SvInputFieldComponent } from '@styloviz/input-field';

const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const RESEND_AFTER_S = 30;
let nextId = 0;

/**
 * Forgot-password card — one email field, then a "check your email" state
 * whose Resend button unlocks after a 30-second countdown.
 *
 * Bind `(requestReset)` to your reset endpoint. While `[pending]` is true the
 * card waits; if `[error]` is set it shows the form again with the reason.
 */
@Component({
  selector: 'app-auth-forgot-password',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [SvAlertBannerComponent, SvButtonComponent, SvIconComponent, SvInputFieldComponent],
  template: `
    <section class="bg-gray-50 px-4 py-12 sm:px-6 sm:py-16 dark:bg-gray-950">
      <div class="mx-auto w-full max-w-md rounded-2xl border border-gray-200 bg-white p-6 shadow-sm sm:p-8 dark:border-white/10 dark:bg-gray-900">
        <span class="flex h-11 w-11 items-center justify-center rounded-xl bg-primary-50 text-primary-700 dark:bg-primary-500/15 dark:text-primary-300" aria-hidden="true">
          <sv-icon name="mail" cssClass="h-5 w-5" />
        </span>

        @if (sent()) {
          <div role="status">
            <h2 class="mt-5 text-2xl font-semibold tracking-tight text-gray-900 dark:text-white">Check your email</h2>
            <p class="mt-2 text-sm leading-relaxed text-gray-600 dark:text-gray-400">
              If an account exists for <span class="font-medium text-gray-900 dark:text-white">{{ email().trim() }}</span>,
              a reset link is on its way. It expires in 60 minutes.
            </p>
          </div>
          <div class="mt-6 flex flex-col gap-2">
            <sv-button btnStyle="outline" variant="neutral" size="lg" [block]="true" [label]="resendLabel()"
                       [disabled]="countdown() > 0 || pending()" (clicked)="send()" />
            <sv-button btnStyle="ghost" variant="neutral" size="lg" [block]="true" label="Use a different email" (clicked)="submitted.set(false)" />
          </div>
        } @else {
          <h2 class="mt-5 text-2xl font-semibold tracking-tight text-gray-900 dark:text-white">Reset your password</h2>
          <p class="mt-2 text-sm leading-relaxed text-gray-600 dark:text-gray-400">
            Enter the email you sign in with and we will send you a link to choose a new password.
          </p>
          @if (error()) {
            <sv-alert-banner class="mt-5 block" variant="danger" alertStyle="soft" size="sm" [dismissible]="false" [message]="error()" />
          }
          <form class="mt-6 flex flex-col gap-4" novalidate (submit)="$event.preventDefault(); submit()">
            <sv-input-field [inputId]="uid + '-email'" label="Email" type="email" placeholder="you@company.com" leadingIcon="mail"
                            autocomplete="email" [required]="true" [(value)]="email" [errorMessage]="emailError()" />
            <sv-button type="submit" size="lg" [block]="true" label="Send reset link" loadingLabel="Sending" [loading]="pending()" />
          </form>
        }

        <a [href]="signInHref()"
           class="mt-6 inline-flex min-h-9 items-center gap-1.5 rounded-md text-sm font-medium text-primary-700 hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary-500 dark:text-primary-300">
          <sv-icon name="arrow-left" cssClass="h-4 w-4" aria-hidden="true" />
          Back to sign in
        </a>
      </div>
    </section>
  `,
})
export class AuthForgotPasswordComponent {
  protected readonly icons = registerSvIcons([arrowLeftIcon, mailIcon]);

  /** True while your reset request runs. */
  readonly pending = input(false);
  /** The server's reason the request failed; empty hides the banner. */
  readonly error = input('');
  /** Where "Back to sign in" goes. */
  readonly signInHref = input('/login');

  /** The validated address to send a reset link to — again on every Resend. */
  readonly requestReset = output<string>();

  protected readonly uid = `forgot-password-${nextId++}`;
  protected readonly email = signal('');
  protected readonly submitted = signal(false);
  protected readonly countdown = signal(0);
  private readonly attempted = signal(false);
  private timer: ReturnType<typeof setInterval> | undefined;

  protected readonly sent = computed(() => this.submitted() && !this.pending() && !this.error());
  protected readonly resendLabel = computed(() => (this.countdown() > 0 ? `Resend in ${this.countdown()} s` : 'Resend email'));
  protected readonly emailError = computed(() => {
    if (!this.attempted()) return '';
    const value = this.email().trim();
    if (!value) return 'Enter your email.';
    return EMAIL.test(value) ? '' : 'That does not look like an email address.';
  });

  constructor() {
    inject(DestroyRef).onDestroy(() => clearInterval(this.timer));
  }

  protected submit(): void {
    this.attempted.set(true);
    if (this.pending() || this.emailError()) return;
    this.send();
  }

  protected send(): void {
    this.requestReset.emit(this.email().trim());
    this.submitted.set(true);
    clearInterval(this.timer);
    this.countdown.set(RESEND_AFTER_S);
    this.timer = setInterval(() => {
      this.countdown.update((s) => s - 1);
      if (this.countdown() <= 0) clearInterval(this.timer);
    }, 1000);
  }
}

