  readonly email: string;
  readonly bio: string;
}

const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const BIO_MAX = 160;
let nextId = 0;

/**
 * Profile settings card — avatar, name, email and a short bio. Save stays
 * disabled until something changes; Discard puts the saved values back.
 *
 * Bind `(save)`, set `[pending]` while it runs and `[error]` if it fails. Pass
 * the saved profile back through `[profile]` and the form is clean again.
 */
@Component({
  selector: 'app-settings-profile',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [SvAlertBannerComponent, SvAvatarComponent, SvButtonComponent, SvInputFieldComponent],
  template: `
    <section class="bg-gray-50 px-4 py-12 sm:px-6 sm:py-16 dark:bg-gray-950">
