        <div class="flex flex-col gap-5 px-5 py-6 sm:px-6">
          @if (error()) {
            <sv-alert-banner variant="danger" alertStyle="soft" size="sm" [dismissible]="false" [message]="error()" />
          }
          <div class="flex items-center gap-4">
            <sv-avatar [name]="name() || profile().name" size="xl" />
