          </div>
          <div class="grid gap-5 sm:grid-cols-2">
            <sv-input-field [inputId]="uid + '-name'" label="Full name" autocomplete="name" [required]="true"
                            [(value)]="name" [errorMessage]="nameError()" />
            <sv-input-field [inputId]="uid + '-email'" label="Email" type="email" leadingIcon="mail" autocomplete="email"
                            [required]="true" [(value)]="email" [errorMessage]="emailError()" />
          </div>
          <sv-input-field [inputId]="uid + '-bio'" label="Bio" [multiline]="true" [maxLength]="bioMax"
                          placeholder="A line about what you work on" [hint]="bioHint()" [(value)]="bio" />
        </div>

        <footer class="flex flex-col-reverse gap-2 border-t border-gray-200 px-5 py-4 sm:flex-row sm:justify-end sm:px-6 dark:border-white/10">
          <sv-button btnStyle="ghost" variant="neutral" label="Discard" [disabled]="!dirty() || pending()" (clicked)="discard()" />
          <sv-button type="submit" label="Save changes" loadingLabel="Saving" [disabled]="!dirty()" [loading]="pending()" />
        </footer>
      </form>
    </section>
  `,
})
export class SettingsProfileComponent {
  protected readonly icons = registerSvIcons([mailIcon]);

  /** The saved profile; the form resets to it whenever it changes. */
  readonly profile = input<ProfileSettings>({
    name: 'Maya Okafor',
    email: 'maya@northwind.io',
    bio: 'Revenue operations lead. I look after billing data and the board pack.',
  });
  /** True while your save request runs. */
  readonly pending = input(false);
  /** The server's reason the save failed; empty hides the banner. */
  readonly error = input('');

  /** The edited profile, trimmed, once it validates. */
  readonly save = output<ProfileSettings>();

  protected readonly uid = `settings-profile-${nextId++}`;
  protected readonly bioMax = BIO_MAX;
  protected readonly name = linkedSignal(() => this.profile().name);
  protected readonly email = linkedSignal(() => this.profile().email);
  protected readonly bio = linkedSignal(() => this.profile().bio);
  private readonly attempted = signal(false);

  protected readonly dirty = computed(() => {
    const saved = this.profile();
    return this.name() !== saved.name || this.email() !== saved.email || this.bio() !== saved.bio;
  });
  protected readonly bioHint = computed(() => `${BIO_MAX - this.bio().length} characters left`);
  protected readonly nameError = computed(() => (this.attempted() && !this.name().trim() ? 'Enter your name.' : ''));
  protected readonly emailError = computed(() => {
    if (!this.attempted()) return '';
    const value = this.email().trim();
    if (!value) return 'Enter your email.';
    return EMAIL.test(value) ? '' : 'That does not look like an email address.';
  });

  protected discard(): void {
    const saved = this.profile();
    this.name.set(saved.name);
    this.email.set(saved.email);
    this.bio.set(saved.bio);
    this.attempted.set(false);
  }

  protected submit(): void {
    this.attempted.set(true);
    if (!this.dirty() || this.pending() || this.nameError() || this.emailError()) return;
    this.save.emit({ name: this.name().trim(), email: this.email().trim(), bio: this.bio().trim() });
  }
}

