              <div class="flex items-baseline justify-between gap-2 text-sm">
                <span [id]="m.labelId" class="font-medium text-gray-900 dark:text-white">{{ m.label }}</span>
                <span class="text-gray-600 tabular-nums dark:text-gray-400">{{ m.text }}</span>
              </div>
              <div class="mt-2 h-2 overflow-hidden rounded-full bg-gray-100 dark:bg-white/10" role="meter"
                   aria-valuemin="0" [attr.aria-valuemax]="m.limit" [attr.aria-valuenow]="m.used"
                   [attr.aria-valuetext]="m.text" [attr.aria-labelledby]="m.labelId">
                <div class="h-full rounded-full" [class]="m.bar" [style.width.%]="m.pct"></div>
              </div>
            </li>
          }
        </ul>

        <div class="flex flex-col gap-3 border-t border-gray-200 px-5 py-5 sm:flex-row sm:items-center sm:justify-between sm:px-6 dark:border-white/10">
          <div class="flex items-center gap-3">
            <span class="flex h-9 w-12 items-center justify-center rounded-md bg-gray-50 ring-1 ring-gray-200 dark:bg-white/5 dark:ring-white/10" aria-hidden="true">
              <sv-icon name="visa" cssClass="h-6 w-8" />
            </span>
            <p class="text-sm">
              <span class="block font-medium text-gray-900 dark:text-white">{{ payment().brand }} ending {{ payment().last4 }}</span>
              <span class="block text-gray-600 dark:text-gray-400">Expires {{ payment().expires }}</span>
            </p>
          </div>
          <sv-button btnStyle="ghost" variant="neutral" size="sm" label="Update card" [disabled]="pending()" (clicked)="updatePayment.emit()" />
        </div>
      </div>
    </section>
  `,
})
export class SettingsBillingPlanComponent {
  protected readonly icons = registerSvIcons([visaIcon]);

  /** The current subscription. */
  readonly plan = input<BillingPlan>({ name: 'Growth', price: '$249', interval: 'month', renewsOn: 'Nov 14, 2026', renewsOnIso: '2026-11-14' });
  /** Metered allowances for this billing period. */
  readonly usage = input<readonly UsageQuota[]>([
    { id: 'seats', label: 'Seats', used: 18, limit: 25, unit: 'seats' },
    { id: 'events', label: 'Tracked events', used: 8_420_000, limit: 10_000_000, unit: 'events' },
    { id: 'storage', label: 'Storage', used: 48, limit: 50, unit: 'GB' },
  ]);
  /** The card on file. */
  readonly payment = input<PaymentMethod>({ brand: 'Visa', last4: '4242', expires: '08/2028' });
  /** True while a plan or payment change runs. */
  readonly pending = input(false);

  /** "Change plan" was clicked. */
  readonly changePlan = output<void>();
  /** "Cancel plan" was clicked — confirm before acting on it. */
  readonly cancelPlan = output<void>();
  /** "Update card" was clicked. */
  readonly updatePayment = output<void>();

  private readonly uid = `billing-plan-${nextId++}`;
  private readonly number = new Intl.NumberFormat('en-US', { notation: 'compact', maximumFractionDigits: 1 });

  protected readonly meters = computed(() =>
    this.usage().map((q) => {
      const pct = q.limit > 0 ? Math.min(100, Math.round((q.used / q.limit) * 100)) : 0;
      return {
        ...q,
        pct,
        labelId: `${this.uid}-${q.id}`,
        text: `${this.number.format(q.used)} of ${this.number.format(q.limit)} ${q.unit}`,
        bar: pct >= 95 ? 'bg-danger-600' : pct >= 80 ? 'bg-warning-500' : 'bg-primary-600',
      };
    }),
  );
}

import { ChangeDetectionStrategy, Component, computed, input, output, signal } from '@angular/core';
import { SvAlertBannerComponent } from '@styloviz/alert-banner';
import { SvAvatarComponent } from '@styloviz/avatar';
import { SvBadgeComponent } from '@styloviz/badge';
import { SvButtonComponent } from '@styloviz/button';
import { registerSvIcons } from '@styloviz/icons';
import { mailIcon } from '@styloviz/icons/glyph/mail';
import { trashIcon } from '@styloviz/icons/glyph/trash';
import { userPlusIcon } from '@styloviz/icons/glyph/user-plus';
import { SvInputFieldComponent } from '@styloviz/input-field';

export type TeamRole = 'Owner' | 'Admin' | 'Member' | 'Viewer';

/** One person in the workspace. */
export interface TeamMember {
  readonly id: string;
  readonly name: string;
  readonly email: string;
  readonly role: TeamRole;
}

const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const ROLES: readonly Exclude<TeamRole, 'Owner'>[] = ['Admin', 'Member', 'Viewer'];
const SELECT =
  'min-h-9 rounded-lg border border-gray-300 bg-white px-3 text-sm text-gray-900 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary-500 disabled:opacity-60 dark:border-white/15 dark:bg-gray-900 dark:text-white';
let nextId = 0;

/**
 * Team members — the people in a workspace with a role picker and Remove for
 * each, and an invite-by-email form. The owner's role is fixed.
 *
 * Bind `(invite)`, `(roleChange)` and `(remove)`; pass the updated list back
 * through `[members]`. `[pending]`/`[error]` cover the invite request.
 */
@Component({
  selector: 'app-settings-team-members',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [SvAlertBannerComponent, SvAvatarComponent, SvBadgeComponent, SvButtonComponent, SvInputFieldComponent],
  template: `
    <section class="bg-gray-50 px-4 py-12 sm:px-6 sm:py-16 dark:bg-gray-950">
      <div class="mx-auto max-w-3xl rounded-2xl border border-gray-200 bg-white shadow-sm dark:border-white/10 dark:bg-gray-900">
        <header class="px-5 py-5 sm:px-6">
          <h2 class="text-lg font-semibold tracking-tight text-gray-900 dark:text-white">Team members</h2>
          <p class="mt-1 text-sm text-gray-600 dark:text-gray-400">{{ members().length }} people have access to this workspace.</p>
        </header>

        <form class="flex flex-col gap-3 border-t border-gray-200 px-5 py-5 sm:flex-row sm:items-start sm:px-6 dark:border-white/10"
              novalidate (submit)="$event.preventDefault(); submit()">
          <sv-input-field class="flex-1" [inputId]="uid + '-email'" type="email" placeholder="teammate@northwind.io" leadingIcon="mail"
                          ariaLabel="Email to invite" [(value)]="email" [errorMessage]="emailError()" />
          <label class="sr-only" [for]="uid + '-role'">Role for the invite</label>
          <select [id]="uid + '-role'" [class]="selectClass" (change)="inviteRole.set(roleOf($event))">
            @for (r of roles; track r) { <option [value]="r" [selected]="r === inviteRole()">{{ r }}</option> }
          </select>
          <sv-button type="submit" icon="user-plus" label="Send invite" loadingLabel="Inviting" [loading]="pending()" />
        </form>
        @if (error()) {
          <sv-alert-banner class="block px-5 pb-5 sm:px-6" variant="danger" alertStyle="soft" size="sm" [dismissible]="false" [message]="error()" />
        }

        <ul class="divide-y divide-gray-200 border-t border-gray-200 dark:divide-white/10 dark:border-white/10">
          @for (m of rows(); track m.id) {
            <li class="flex flex-wrap items-center gap-3 px-5 py-4 sm:flex-nowrap sm:px-6">
              <sv-avatar [name]="m.name" size="md" />
              <div class="min-w-0 flex-1">
                <p class="truncate text-sm font-medium text-gray-900 dark:text-white">{{ m.name }}</p>
                <p class="truncate text-sm text-gray-600 dark:text-gray-400">{{ m.email }}</p>
              </div>
              @if (m.role === 'Owner') {
                <sv-badge size="sm" variant="primary" label="Owner" />
              } @else {
                <label class="sr-only" [for]="m.selectId">Role for {{ m.name }}</label>
                <select [id]="m.selectId" [class]="selectClass" (change)="changeRole(m.id, roleOf($event))">
                  @for (r of roles; track r) { <option [value]="r" [selected]="r === m.role">{{ r }}</option> }
                </select>
                <sv-button btnStyle="ghost" variant="danger" size="sm" icon="trash" [ariaLabel]="m.removeLabel" (clicked)="remove.emit(m.id)" />
              }
            </li>
          }
        </ul>
      </div>
    </section>
  `,
})
export class SettingsTeamMembersComponent {
  protected readonly icons = registerSvIcons([mailIcon, trashIcon, userPlusIcon]);

  /** The workspace's members. */
  readonly members = input<readonly TeamMember[]>([
    { id: 'u1', name: 'Maya Okafor', email: 'maya@northwind.io', role: 'Owner' },
    { id: 'u2', name: 'Lucas Ferreira', email: 'lucas@northwind.io', role: 'Admin' },
    { id: 'u3', name: 'Priya Raman', email: 'priya@northwind.io', role: 'Member' },
    { id: 'u4', name: 'Tom Achterberg', email: 'tom@northwind.io', role: 'Viewer' },
  ]);
  /** True while your invite request runs. */
  readonly pending = input(false);
  /** Why the last invite failed; empty hides the banner. */
  readonly error = input('');

  /** A valid email and the role to invite them with. */
  readonly invite = output<{ readonly email: string; readonly role: TeamRole }>();
  /** A member's new role. */
  readonly roleChange = output<{ readonly id: string; readonly role: TeamRole }>();
  /** The id of the member to remove — confirm before acting on it. */
  readonly remove = output<string>();

  protected readonly uid = `team-members-${nextId++}`;
  protected readonly roles = ROLES;
  protected readonly selectClass = SELECT;
  protected readonly email = signal('');
  protected readonly inviteRole = signal<TeamRole>('Member');
  private readonly attempted = signal(false);

  protected readonly rows = computed(() =>
    this.members().map((m) => ({ ...m, selectId: `${this.uid}-${m.id}`, removeLabel: `Remove ${m.name}` })),
  );
  protected readonly emailError = computed(() => {
    if (!this.attempted()) return '';
    const value = this.email().trim();
    if (!value) return 'Enter an email to invite.';
    if (!EMAIL.test(value)) return 'That does not look like an email address.';
    return this.members().some((m) => m.email === value.toLowerCase()) ? 'They are already on the team.' : '';
  });

  /** The role a select now shows, checked against the list. */
  protected roleOf(event: Event): Exclude<TeamRole, 'Owner'> {
    const value = (event.target as HTMLSelectElement).value;
    return ROLES.find((r) => r === value) ?? 'Member';
  }

  protected changeRole(id: string, role: TeamRole): void {
    this.roleChange.emit({ id, role });
  }

  protected submit(): void {
    this.attempted.set(true);
    if (this.pending() || this.emailError()) return;
    this.invite.emit({ email: this.email().trim().toLowerCase(), role: this.inviteRole() });
    this.email.set('');
    this.attempted.set(false);
  }
}
